import cv2, glob, os

# Convert keyframes to grayscale in place
for path in sorted(glob.glob('/root/keyframes_*.png')):
    img = cv2.imread(path)
    if img is None:
        raise SystemExit(f'Failed to read {path}')
    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
    cv2.imwrite(path, gray)
